<?php

# @autogenerated
declare(strict_types=1);
namespace Civi\Lughauth\Features\Document\Template\Domain\Event;

use Override;

use Civi\Lughauth\Features\Document\Template\Domain\Template;
use Civi\Lughauth\Shared\Event\PublicEvent;

class TemplateEnableEvent extends TemplateUpdateEvent
{
  public function __construct(
    Template $payload
,
       Template $original  ) {
   parent::__construct($payload, $original);  }
  #[Override]
  public function eventType(): string
  {
    return 'template.enable';
  }
  #[Override]
  public function schemaVersion(): string  {
    return 'v1';
  }
  #[Override]
  public function payload(): array  {
    return $this->payload->asPublicJson();
  }
  #[Override]
  public function original(): array  {
    return $this->original->asPublicJson();
  }
}
